mapper.select:
select mn.*, p.P_Name as projectName, con.Con_Name as contractName,con.Con_Money_Total as contractTotalMoney, con.Con_Party_B_Id as contractCompanyId, c5.C_Name as contractCompanyName, con.Con_Bid_Amt AS contractControlPrice, c1.C_Name as sfaCostConsultantUnitName, c2.C_Name as sfaSupervisionUnitName, c3.C_Name as sfaCostConsultantUnitNameOld, c4.C_Name as sfaSupervisionUnitNameOld from Settlement_First_Audit_Change_Log mn left join Pre_Project p on p.P_Id=mn.project_id left join Con_Contract con on con.Con_Id=mn.contract_id left join SYS_Company c1 on c1.C_Id=mn.sfa_cost_consultant_unit left join SYS_Company c2 on c2.C_Id=mn.sfa_supervision_unit left join SYS_Company c3 on c3.C_Id=mn.sfa_cost_consultant_unit_old left join SYS_Company c4 on c4.C_Id=mn.sfa_supervision_unit_old left join SYS_Company c5 on c5.C_Id=con.Con_Party_B_Id
mn.state != 3
and mn.sfa_id=#{params.sfaId}
